package com.digitaloffice.document; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface DocumentRepository extends JpaRepository<Document,UUID>{List<Document> findByProjectIdAndStatus(UUID p,DocumentStatus s); @org.springframework.data.jpa.repository.Query("select d from Document d where d.status = com.digitaloffice.document.DocumentStatus.ACTIVE and lower(d.title) like lower(concat('%', :keyword, '%')) and d.projectId in :projects") List<Document> searchByTitle(@org.springframework.data.repository.query.Param("keyword") String keyword,@org.springframework.data.repository.query.Param("projects") Collection<UUID> projects);}
